changeSet.sql:
INSERT INTO configuracao_grafico_dashboard (organizacao_id, tipo_grafico, ativo, ordem_exibicao, created_at, updated_at) SELECT o.id, 'CONSULTAS_POR_PERIODO', true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM organizacao o WHERE NOT EXISTS ( SELECT 1 FROM configuracao_grafico_dashboard cgd WHERE cgd.organizacao_id = o.id AND cgd.tipo_grafico = 'CONSULTAS_POR_PERIODO' );
INSERT INTO configuracao_grafico_dashboard (organizacao_id, tipo_grafico, ativo, ordem_exibicao, created_at, updated_at) SELECT o.id, 'AGENDAMENTOS_DIAS_SEMANA', true, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM organizacao o WHERE NOT EXISTS ( SELECT 1 FROM configuracao_grafico_dashboard cgd WHERE cgd.organizacao_id = o.id AND cgd.tipo_grafico = 'AGENDAMENTOS_DIAS_SEMANA' );
INSERT INTO configuracao_grafico_dashboard (organizacao_id, tipo_grafico, ativo, ordem_exibicao, created_at, updated_at) SELECT o.id, 'SALDO_FINANCEIRO', true, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM organizacao o WHERE NOT EXISTS ( SELECT 1 FROM configuracao_grafico_dashboard cgd WHERE cgd.organizacao_id = o.id AND cgd.tipo_grafico = 'SALDO_FINANCEIRO' );
INSERT INTO configuracao_grafico_dashboard (organizacao_id, tipo_grafico, ativo, ordem_exibicao, created_at, updated_at) SELECT o.id, 'MEDICOS_POR_ESPECIALIDADE', true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM organizacao o WHERE NOT EXISTS ( SELECT 1 FROM configuracao_grafico_dashboard cgd WHERE cgd.organizacao_id = o.id AND cgd.tipo_grafico = 'MEDICOS_POR_ESPECIALIDADE' );
